import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int pointer = 0, length = 0;

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + c - '0';
                c = read();
            }
            return value;
        }

        private int read() throws IOException {
            if (pointer == length) {
                length = in.read(buffer);
                pointer = 0;
                if (length == -1) return -1;
            }
            return buffer[pointer++];
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        int n = fs.nextInt();
        int m = fs.nextInt();

        int[] incompatible = new int[n];
        for (int i = 0; i < m; i++) {
            int x = fs.nextInt() - 1;
            int y = fs.nextInt() - 1;
            incompatible[x] |= 1 << y;
            incompatible[y] |= 1 << x;
        }

        int total = 1 << n;
        boolean[] valid = new boolean[total];
        valid[0] = true;
        int answer = 0;

        for (int mask = 1; mask < total; mask++) {
            int bit = mask & -mask;
            int ingredient = Integer.numberOfTrailingZeros(bit);
            int rest = mask ^ bit;

            valid[mask] = valid[rest] && (incompatible[ingredient] & rest) == 0;
            if (valid[mask]) answer++;
        }

        System.out.println(answer);
    }
}
